def heaviestPath(n, edges):
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b, w in edges:
        adj[a].append((b, w))
        indeg[b] += 1
    best = [0] * n
    stack = [i for i in range(n) if indeg[i] == 0]
    while stack:
        u = stack.pop()
        for v, w in adj[u]:
            if best[u] + w > best[v]:
                best[v] = best[u] + w
            indeg[v] -= 1
            if indeg[v] == 0:
                stack.append(v)
    return max(best)
